describe('errorHandler', () => {
  it('logs the error and responds with a generic 500 JSON body', () => {
    const consoleError = vi.spyOn(console, 'error').mockImplementation(() => {});
    const res = mockRes();
    const next = vi.fn();

    errorHandler(new Error('scoring blew up'), {} as never, res, next);

    expect(res.status).toHaveBeenCalledWith(500);
    expect(res.json).toHaveBeenCalledWith({
      error: 'Something went wrong on the server. Please try again.',
    });
    expect(next).not.toHaveBeenCalled();
    consoleError.mockRestore();
  });

  it('responds with HTTP 400 and {"error":"Request body is not valid JSON."} when the error is a SyntaxError with status 400', () => {
    const consoleError = vi.spyOn(console, 'error').mockImplementation(() => {});
    const res = mockRes();
    const next = vi.fn();

    const err = new SyntaxError('unexpected token');
    (err as any).status = 400;

    errorHandler(err, {} as never, res, next);

    expect(res.status).toHaveBeenCalledWith(400);
    expect(res.json).toHaveBeenCalledWith({ error: 'Request body is not valid JSON.' });
    expect(next).not.toHaveBeenCalled();
    consoleError.mockRestore();
  });

  it('responds with HTTP 500 for a SyntaxError without a status status when the status 400 is not found in the error', () => {
    const consoleError = vi.spyOn(console, 'error').mockImplementation(() => {});
    const res = mockRes();
    const next = vi.fn();

    const err = new SyntaxError('unexpected token');
    // No status property

    errorHandler(err, {} as never, res, next);

    expect(res.status).toHaveBeenCalledWith(500);
    expect(res.json).toHaveBeenCalledWith({
      error: 'Something went wrong on the server. Please try again.',
    });
    expect(next).not.toHaveBeenCalled();
    consoleError.mockRestore();
  });

